"use client";

import Image from "next/image";
import { useState, ViewTransition } from "react";
import { cn } from "@/lib/utils";

export function ProductGallery({ images, name, productId }: { images: { url: string; alt: string | null }[]; name: string; productId: string }) {
  const [active, setActive] = useState(0);
  const [zoom, setZoom] = useState<{ x: number; y: number } | null>(null);
  const current = images[active];
  return (
    <div className="flex flex-col-reverse gap-3 self-start sm:flex-row">
      <div className="no-scrollbar flex gap-2 overflow-x-auto sm:flex-col">
        {images.map((img, i) => (
          <button
            key={img.url}
            onClick={() => setActive(i)}
            onMouseEnter={() => setActive(i)}
            className={cn("press relative h-16 w-16 shrink-0 overflow-hidden rounded-md border-2 bg-white transition", i === active ? "border-brass shadow-md" : "border-line opacity-80 hover:opacity-100")}
            aria-label={`Show image ${i + 1}`}
            aria-current={i === active}
          >
            <Image src={img.url} alt="" fill sizes="64px" className="object-contain p-1" />
          </button>
        ))}
      </div>
      <div className="min-w-0 flex-1">
        {/* Same name as the listing card image, so the card morphs into this hero on navigation. */}
        <ViewTransition name={`product-${productId}`} share="morph" default="none">
          <div
            data-pdp-image
            className="relative aspect-square w-full cursor-zoom-in overflow-hidden rounded-xl border border-line bg-white"
            onMouseMove={(e) => {
              const r = e.currentTarget.getBoundingClientRect();
              setZoom({ x: ((e.clientX - r.left) / r.width) * 100, y: ((e.clientY - r.top) / r.height) * 100 });
            }}
            onMouseLeave={() => setZoom(null)}
          >
            {current && (
              <Image
                key={current.url}
                src={current.url}
                alt={current.alt ?? name}
                fill
                priority
                sizes="(max-width: 768px) 100vw, 50vw"
                className="animate-fade-in object-contain p-4 transition-transform duration-200 ease-out"
                style={zoom ? { transform: "scale(1.8)", transformOrigin: `${zoom.x}% ${zoom.y}%` } : undefined}
              />
            )}
          </div>
        </ViewTransition>
        {images.length > 1 && (
          <div className="mt-3 flex justify-center gap-1.5 sm:hidden">
            {images.map((img, i) => <span key={img.url} className={cn("h-1.5 rounded-full transition-all duration-300", i === active ? "w-5 bg-brass" : "w-1.5 bg-line")} />)}
          </div>
        )}
      </div>
    </div>
  );
}
