"use client";

import { useState } from "react";
import { MapPin, Truck } from "lucide-react";

// Delivery estimate by PIN zone from Cheyyur (603302). First two digits identify the postal circle.
function estimate(pin: string) {
  const p2 = Number(pin.slice(0, 2));
  const p3 = Number(pin.slice(0, 3));
  if (p3 >= 600 && p3 <= 605) return { min: 1, max: 3, label: "Chennai & Chengalpattu region" };
  if (p2 >= 60 && p2 <= 64) return { min: 2, max: 4, label: "Tamil Nadu & Puducherry" };
  if ((p2 >= 50 && p2 <= 59) || (p2 >= 67 && p2 <= 69)) return { min: 3, max: 6, label: "South India" };
  return { min: 5, max: 9, label: "Rest of India" };
}

function addWorkingDays(days: number) {
  const d = new Date();
  let added = 0;
  while (added < days) {
    d.setDate(d.getDate() + 1);
    if (d.getDay() !== 0) added++;
  }
  return d.toLocaleDateString("en-IN", { weekday: "short", day: "numeric", month: "short" });
}

export function PincodeCheck() {
  const [pin, setPin] = useState("");
  const [result, setResult] = useState<{ text: string; zone: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Prefill the visitor's last PIN when they focus the box (avoids a hydration mismatch).
  const prefill = () => {
    if (pin) return;
    try {
      const saved = localStorage.getItem("sm_pin");
      if (saved && /^[1-9]\d{5}$/.test(saved)) setPin(saved);
    } catch {}
  };

  const check = () => {
    if (!/^[1-9]\d{5}$/.test(pin)) {
      setResult(null);
      return setError("Enter a valid 6-digit PIN code");
    }
    setError(null);
    const e = estimate(pin);
    setResult({ text: `${addWorkingDays(e.min)} – ${addWorkingDays(e.max)}`, zone: e.label });
    try { localStorage.setItem("sm_pin", pin); } catch {}
  };

  return (
    <div className="rounded-md bg-paper p-3 text-sm">
      <p className="mb-2 flex items-center gap-1.5 font-medium"><MapPin className="h-4 w-4 text-brass" aria-hidden /> Check delivery</p>
      <div className="flex gap-2">
        <input
          value={pin}
          onChange={(e) => setPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
          onKeyDown={(e) => e.key === "Enter" && check()}
          onFocus={prefill}
          inputMode="numeric"
          placeholder="Enter PIN code"
          aria-label="PIN code"
          className="input py-1.5"
        />
        <button onClick={check} className="btn-outline press px-3 py-1.5 text-sm">Check</button>
      </div>
      {error && <p className="mt-1.5 text-xs text-danger">{error}</p>}
      {result && (
        <p key={result.text} className="animate-fade-up mt-2 flex gap-1.5 text-xs">
          <Truck className="h-4 w-4 shrink-0 text-success" aria-hidden />
          <span>Estimated delivery <b>{result.text}</b> · {result.zone}</span>
        </p>
      )}
    </div>
  );
}
