"use client";

import Script from "next/script";
import { useEffect, useRef, useState } from "react";

declare global {
  interface Window {
    RazorpayAffordabilitySuite?: new (config: { key: string; amount: number }) => { render: () => void };
  }
}

/** Razorpay Affordability Widget — shows the live EMI / cardless EMI / pay-later offers for this amount. */
export function AffordabilityWidget({ keyId, amount }: { keyId?: string; amount: number }) {
  const [ready, setReady] = useState(false);
  const rendered = useRef<number | null>(null);
  useEffect(() => {
    if (!ready || !keyId || !window.RazorpayAffordabilitySuite || rendered.current === amount) return;
    try {
      new window.RazorpayAffordabilitySuite({ key: keyId, amount }).render();
      rendered.current = amount;
    } catch (e) {
      console.warn("Affordability widget failed", e);
    }
  }, [ready, keyId, amount]);
  if (!keyId) return null;
  return (
    <>
      <Script src="https://cdn.razorpay.com/widgets/affordability/affordability.js" strategy="lazyOnload" onReady={() => setReady(true)} />
      <div id="razorpay-affordability-widget" className="min-h-0" />
    </>
  );
}
