"use client";

import { useActionState, useState } from "react";
import { Star } from "lucide-react";
import { submitReview } from "@/app/actions/account";

export function ReviewForm({ productId }: { productId: string }) {
  const [state, action, pending] = useActionState(submitReview, undefined);
  const [rating, setRating] = useState(0);
  if (state?.ok) return <p className="rounded-md bg-success/10 p-3 text-sm text-success">Thanks! Your review has been published.</p>;
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="productId" value={productId} />
      <input type="hidden" name="rating" value={rating} />
      <div className="flex gap-1" role="radiogroup" aria-label="Rating">
        {[1, 2, 3, 4, 5].map((i) => (
          <button type="button" key={i} onClick={() => setRating(i)} aria-label={`${i} star`} aria-checked={rating === i} role="radio">
            <Star className={i <= rating ? "h-7 w-7 fill-brass text-brass" : "h-7 w-7 text-line"} />
          </button>
        ))}
      </div>
      <input name="title" placeholder="Headline" className="input" maxLength={120} />
      <textarea name="body" placeholder="What did you like or dislike?" rows={3} className="input" maxLength={2000} />
      {state?.error && <p className="text-sm text-danger">{state.error}</p>}
      <button disabled={pending || !rating} className="btn-dark">Submit review</button>
    </form>
  );
}
