"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState, useTransition } from "react";
import { Lock, ShoppingCart, Zap } from "lucide-react";
import { addToCart } from "@/app/actions/cart";
import { formatINR } from "@/lib/money";
import { whatsappLink } from "@/lib/site";
import { useStoreUI } from "./StoreUI";
import { WishlistButton } from "./WishlistButton";
import { PincodeCheck } from "./PincodeCheck";
import { ShareButton } from "./ShareButton";

type Props = { productId: string; name: string; price: number; mrp: number; stock: number; engravingAvailable: boolean };

export function BuyBox({ productId, name, price, mrp, stock, engravingAvailable }: Props) {
  const router = useRouter();
  const { toast, flyToCart, openCart } = useStoreUI();
  const [qty, setQty] = useState(1);
  const [engrave, setEngrave] = useState(false);
  const [text, setText] = useState("");
  const [pending, start] = useTransition();
  const boxRef = useRef<HTMLDivElement>(null);
  const [showSticky, setShowSticky] = useState(false);

  // Mobile sticky bar appears once the main buttons scroll out of view.
  useEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => setShowSticky(!e.isIntersecting && e.boundingClientRect.top < 0));
    io.observe(el);
    return () => io.disconnect();
  }, []);

  const submit = (buyNow: boolean) =>
    start(async () => {
      if (engrave && !text.trim()) return toast("Enter the text to engrave, or untick engraving", "error");
      const res = await addToCart({ productId, quantity: qty, engravingText: engrave ? text : "" });
      if (!res.ok) return toast(res.error ?? "Could not add to cart", "error");
      if (buyNow) return router.push("/checkout");
      flyToCart(document.querySelector<HTMLElement>("[data-pdp-image]"));
      toast(`Added ${qty} × “${name}” to cart`, "success");
      setTimeout(openCart, 650);
    });

  const inStock = stock > 0;
  return (
    <>
      <div className="card space-y-4 p-4">
        <p className="text-2xl font-semibold tabular-nums">{formatINR(price * qty)}</p>
        {inStock ? (
          <p className="font-semibold text-success">{stock <= 5 ? <span className="text-warn">Only {stock} left in stock — order soon.</span> : "In stock"}</p>
        ) : (
          <p className="font-semibold text-danger">Currently unavailable</p>
        )}
        <PincodeCheck />
        {inStock && (
          <>
            <label className="flex items-center gap-2 text-sm">
              Quantity
              <select value={qty} onChange={(e) => setQty(Number(e.target.value))} className="rounded-md border border-line bg-paper px-2 py-1.5">
                {Array.from({ length: Math.min(stock, 20) }, (_, i) => i + 1).map((n) => <option key={n} value={n}>{n}</option>)}
              </select>
            </label>

            {engravingAvailable && (
              <div className="rounded-md border border-brass/40 bg-brass-light/40 p-3">
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input type="checkbox" checked={engrave} onChange={(e) => setEngrave(e.target.checked)} className="h-4 w-4 accent-brass" />
                  Add laser engraving (free)
                </label>
                <div className={`grid transition-[grid-template-rows] duration-300 ease-out ${engrave ? "grid-rows-[1fr]" : "grid-rows-[0fr]"}`}>
                  <div className="overflow-hidden">
                    <input
                      value={text}
                      onChange={(e) => setText(e.target.value.slice(0, 60))}
                      placeholder="Name / message (max 60 characters)"
                      className="input mt-2"
                      maxLength={60}
                      tabIndex={engrave ? 0 : -1}
                    />
                    <p className="mt-1 text-right text-xs text-muted">{text.length}/60</p>
                  </div>
                </div>
              </div>
            )}

            <div ref={boxRef} className="space-y-2.5">
              <button disabled={pending} onClick={() => submit(false)} className="btn-brass press w-full rounded-full py-3">
                <ShoppingCart className="h-4 w-4" aria-hidden /> {pending ? "Adding…" : "Add to Cart"}
              </button>
              <button disabled={pending} onClick={() => submit(true)} className="btn-primary press w-full rounded-full py-3">
                <Zap className="h-4 w-4" aria-hidden /> Buy Now
              </button>
            </div>
          </>
        )}
        <p className="flex items-center gap-1.5 text-xs text-muted"><Lock className="h-3.5 w-3.5" aria-hidden /> Secure transaction via Razorpay</p>
        <WishlistButton productId={productId} name={name} variant="full" />
        <div className="flex gap-2">
          <a href={whatsappLink(`Hi, I'm interested in: ${name}`)} target="_blank" rel="noopener noreferrer" className="btn-outline press flex-1 text-sm">Ask on WhatsApp</a>
          <ShareButton title={name} />
        </div>
      </div>

      {inStock && (
        <div
          className={`fixed inset-x-0 bottom-0 z-40 border-t border-line bg-white/95 px-4 py-3 shadow-[0_-8px_24px_-12px_rgb(0_0_0/0.25)] backdrop-blur transition duration-300 ease-out lg:hidden ${showSticky ? "translate-y-0" : "pointer-events-none translate-y-full"}`}
          aria-hidden={!showSticky}
        >
          <div className="flex items-center gap-3">
            <div className="min-w-0 flex-1">
              <p className="truncate text-xs text-muted">{name}</p>
              <p className="font-semibold">{formatINR(price)} {mrp > price && <s className="text-xs font-normal text-muted">{formatINR(mrp)}</s>}</p>
            </div>
            <button disabled={pending} tabIndex={showSticky ? 0 : -1} onClick={() => submit(false)} className="btn-brass press rounded-full px-5">Add</button>
            <button disabled={pending} tabIndex={showSticky ? 0 : -1} onClick={() => submit(true)} className="btn-primary press rounded-full px-5">Buy</button>
          </div>
        </div>
      )}
    </>
  );
}
